<script setup lang="ts">
import { resolveAssetUrl } from '../../api/http'
import {onMounted,reactive,ref} from 'vue';import{useRouter}from'vue-router';import{ElMessage,ElMessageBox}from'element-plus';import{getReceivingOrder,getReceivingOrderItems,getReceivingOrderItem,importReceivingOrderExcel,updateReceivingOrder}from'../../api/receivingOrder';import{getSuppliers}from'../../api/supplier';import type{OrderItemListVO,ReceivingOrder,ReceivingOrderItem,Supplier}from'../../api/types';
const props=defineProps<{id:string}>();const router=useRouter();const order=ref<ReceivingOrder>();const items=ref<OrderItemListVO[]>([]);const detailVisible=ref(false);const detailLoading=ref(false);const detailItem=ref<ReceivingOrderItem>();const suppliers=ref<Supplier[]>([]);const total=ref(0);const loading=ref(false);const importing=ref(false);const editing=ref(false);const fileInput=ref<HTMLInputElement>();const page=reactive({pageNum:0,pageSize:10});const form=reactive({supplierId:undefined as number|undefined,number:undefined as number|undefined,receiveDate:'',temperature:'',transport:''});const supplierCode=ref('');const productName=ref('');const barcode=ref('');const checkStatus=ref<'UNCHECKED'|'PASS'|'FAIL'|''>('');
async function load(){loading.value=true;try{order.value=await getReceivingOrder(Number(props.id));const d=await getReceivingOrderItems({orderId:Number(props.id),...page,supplierCode:supplierCode.value||undefined,productName:productName.value||undefined,barcode:barcode.value||undefined,checkStatus:checkStatus.value||undefined});items.value=d.list||[];total.value=d.total||0;Object.assign(form,{supplierId:order.value.supplierId,number:order.value.number,receiveDate:order.value.receiveDate,temperature:order.value.temperature||'',transport:order.value.transport||''})}catch(e:any){ElMessage.error(e.message||'加载失败')}finally{loading.value=false}}
function searchItems(){page.pageNum=0;load()}
async function loadSuppliers(){const d=await getSuppliers({pageNum:0,pageSize:20});suppliers.value=d.list||[]}function selectFile(){fileInput.value?.click()}async function onFileChange(e:Event){const input=e.target as HTMLInputElement;const f=input.files?.[0];if(!f)return;importing.value=true;try{const r=await importReceivingOrderExcel(Number(props.id),f);await ElMessageBox.alert(`<div style="line-height:2"><div><b>Success:</b> ${r?.success ?? 0}</div><div><b>Skip:</b> ${r?.skip ?? 0}</div></div>`, '收货单导入完成', { dangerouslyUseHTMLString:true, confirmButtonText:'确定' });page.pageNum=0;await load()}catch(e:any){ElMessage.error(e.message||'导入失败')}finally{importing.value=false;input.value=''}}
async function save(){if(!form.supplierId)return ElMessage.warning('请选择供应商');try{await updateReceivingOrder(Number(props.id),{supplierId:form.supplierId,number:form.number,receiveDate:form.receiveDate,temperature:form.temperature,transport:form.transport});editing.value=false;ElMessage.success('修改成功');await load()}catch(e:any){ElMessage.error(e.message||'修改失败')}}
function cs(v?:string){return({UNCHECKED:'未点货',PASS:'通过',FAIL:'异常'}as any)[v||'']||'-'}async function openDetail(itemId:number){detailVisible.value=true;detailLoading.value=true;try{detailItem.value=await getReceivingOrderItem(itemId)}catch(e:any){detailVisible.value=false;ElMessage.error(e.message||'加载详情失败')}finally{detailLoading.value=false}}onMounted(()=>{load();loadSuppliers()})
</script>
<template><div><div class="page-title"><div><h2>收货单详情</h2><p>收货单 #{{id}}</p></div><div><el-button @click="router.back()">返回</el-button><el-button @click="selectFile" :loading="importing">导入 Excel</el-button><el-button type="primary" @click="editing=true">修改</el-button><el-button v-if="order?.progress!=='COMPLETED'" type="success" @click="router.push(`/receiving-orders/${id}/check`)">开始点货</el-button><input ref="fileInput" type="file" accept=".xlsx,.xls" hidden @change="onFileChange"/></div></div><el-card shadow="never" class="mb16"><el-descriptions :column="4" border><el-descriptions-item label="供应商">{{order?.supplierName||'-'}}</el-descriptions-item><el-descriptions-item label="Number">{{order?.number??'-'}}</el-descriptions-item><el-descriptions-item label="收货日期">{{order?.receiveDate||'-'}}</el-descriptions-item><el-descriptions-item label="进度">{{order?.progress||'-'}}</el-descriptions-item><el-descriptions-item label="温度">{{order?.temperature||'-'}}</el-descriptions-item><el-descriptions-item label="运输公司">{{order?.transport||'-'}}</el-descriptions-item></el-descriptions></el-card><el-card shadow="never"><template #header><div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap"><span>货单明细</span><el-input v-model="supplierCode" placeholder="货号" clearable style="width:140px" @keyup.enter="searchItems"/><el-input v-model="productName" placeholder="商品名称" clearable style="width:180px" @keyup.enter="searchItems"/><el-input v-model="barcode" placeholder="Barcode" clearable style="width:180px" @keyup.enter="searchItems"/><el-select v-model="checkStatus" clearable placeholder="状态" style="width:120px" @change="searchItems"><el-option label="全部" value=""/><el-option label="未点货" value="UNCHECKED"/><el-option label="已点货" value="PASS"/><el-option label="异常" value="FAIL"/></el-select><el-button type="primary" @click="searchItems">查询</el-button></div></template><el-table :data="items" v-loading="loading" stripe><el-table-column prop="supplierCode" label="货号" width="140"/><el-table-column prop="productName" label="商品名称" min-width="220"/><el-table-column prop="orderQty" label="订单箱数" width="100"/><el-table-column prop="total" label="应到个数" width="100"/><el-table-column prop="barcode" label="Barcode" min-width="150"/><el-table-column prop="expiryDate" label="有效期" width="150"/><el-table-column label="点货状态" width="100"><template #default="{row}"><el-tag :type="row.checkStatus==='PASS'?'success':row.checkStatus==='FAIL'?'danger':'info'">{{cs(row.checkStatus)}}</el-tag></template></el-table-column><el-table-column label="操作" width="90" fixed="right"><template #default="{row}"><el-button link type="primary" @click="openDetail(row.id)">详情</el-button></template></el-table-column></el-table><div class="pagination"><el-pagination :current-page="page.pageNum+1" :page-size="page.pageSize" :total="total" layout="total,prev,pager,next" @current-change="(p:number)=>{page.pageNum=p-1;load()}"/></div></el-card><el-dialog v-model="editing" title="修改收货单" width="520px"><el-form label-width="90px"><el-form-item label="供应商" required><el-select v-model="form.supplierId" style="width:100%"><el-option v-for="s in suppliers" :key="s.id" :label="s.supplierName" :value="s.id"/></el-select></el-form-item><el-form-item label="Number"><el-input-number v-model="form.number" :min="0" :precision="0"/></el-form-item><el-form-item label="收货日期"><el-date-picker v-model="form.receiveDate" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="温度"><el-input v-model="form.temperature"/></el-form-item><el-form-item label="运输公司"><el-input v-model="form.transport"/></el-form-item></el-form><template #footer><el-button @click="editing=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog><el-dialog v-model="detailVisible" title="货单明细详情" width="620px"><div v-loading="detailLoading"><el-descriptions v-if="detailItem" :column="2" border><el-descriptions-item label="货号">{{detailItem.supplierCode||'-'}}</el-descriptions-item><el-descriptions-item label="商品名称">{{detailItem.productName||'-'}}</el-descriptions-item><el-descriptions-item label="箱规">{{detailItem.cartonQty??'-'}}</el-descriptions-item><el-descriptions-item label="订单箱数">{{detailItem.orderQty??'-'}}</el-descriptions-item><el-descriptions-item label="应到个数">{{detailItem.total??'-'}}</el-descriptions-item><el-descriptions-item label="Barcode">{{detailItem.barcode||'-'}}</el-descriptions-item><el-descriptions-item label="有效期">{{detailItem.expiryDate||'-'}}</el-descriptions-item><el-descriptions-item label="点货状态">{{cs(detailItem.checkStatus)}}</el-descriptions-item><el-descriptions-item label="实际来货个数">{{detailItem.actualQty??'-'}}</el-descriptions-item><el-descriptions-item label="破损数">{{detailItem.damageQty??'-'}}</el-descriptions-item><el-descriptions-item label="类型">{{detailItem.category||'-'}}</el-descriptions-item><el-descriptions-item label="糖等级">{{detailItem.sugar||'-'}}</el-descriptions-item><el-descriptions-item label="单价">{{detailItem.unitPrice??'-'}}</el-descriptions-item><el-descriptions-item label="备注" :span="2">{{detailItem.remark||'-'}}</el-descriptions-item><el-descriptions-item label="破损图片" :span="2"><div v-if="detailItem.damageImgList?.length" style="display:flex;gap:6px"><el-image v-for="(url,i) in detailItem.damageImgList" :key="url+i" :src="resolveAssetUrl(url)" fit="cover" style="width:64px;height:64px" :preview-src-list="detailItem.damageImgList?.map(resolveAssetUrl)" :initial-index="i"/></div><span v-else>-</span></el-descriptions-item></el-descriptions><el-empty v-else description="暂无数据"/></div></el-dialog></div></template>
